.theme-clean-meow {
  display: flex;
  justify-content: center;
  width: 100%;
  padding: 0 5px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  margin: 10px auto;
  position: relative;
  min-height: 100px;
