.meow-collapsible {
  width: 100%;
  margin: 10px 0;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(0,0,0,0.06);
}
.meow-summary {
  list-style: none;
  cursor: pointer;
  background: #fff;
  padding: 12px 15px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #555;
}
.meow-summary::-webkit-details-marker { display: none; }
.meow-summary::after {
  content: '▶';
  font-size: 12px;
  transition: transform 0.3s;
  color: #ccc;
}
.meow-collapsible[open] .meow-summary::after {
  transform: rotate(90deg);
}
</style>
</head>
<body>

<details class="meow-collapsible" open>
  <summary class="meow-summary">
    <span>🐾 喵喵多选器 <small style="font-weight:normal; color:#999; margin-left:8px;">(点击展开/收起)</small></span>
  </summary>

  <div class="theme-clean-meow">
    <div class="cat-decoration top-right">🐱</div>
    <div class="cat-decoration bottom-left">🐾</div>

    <div class="card-clean-meow">
      <div class="clean-header">
        <div>选项列表</div>
        <span>点击选项内容自动追加到输入框</span>
      </div>

      <div class="button-group-clean" id="button-group"></div>

      <div class="clean-footer">
        ✨ 选择完毕后直接发送即可 ✨
      </div>

      <!-- 数据源 -->
      <div id="raw-data" style="display:none">$1</div>
    </div>
  </div>
</details>

<script>
function appendToInput(text) {
  try {
    // 优先尝试特定的 API 触发
    if (window.parent && window.parent.triggerSlash) {
      window.parent.triggerSlash(`/appendinput ${text}`);
      return;
    }
    // 通用的输入框定位逻辑
    const doc = window.parent ? window.parent.document : document;
    const input = doc.querySelector('#send_textarea') || 
                 doc.querySelector('textarea[placeholder*="发送"]') ||
                 doc.querySelector('textarea') ||
                 doc.querySelector('input[type="text"]');

    if (input) {
      const currentValue = input.value.trim();
      input.value = currentValue ? `${currentValue} ${text}` : text;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.focus();
    }
  } catch (error) {
    console.error('追加内容失败:', error);
  }
}

(function initButtons() {
  const rawData = document.getElementById('raw-data');
  const buttonGroup = document.getElementById('button-group');
  if (!rawData || !buttonGroup) return;

  // 处理输入数据，过滤空行
  const lines = rawData.textContent.trim().split(/\r?\n/).filter(l => l.trim() !== '');

  lines.forEach(line => {
    // 清洗数据：去掉行号如 "1. " 或 "A. "
    const cleanText = line.trim().replace(/^[A-Za-z0-9]+[\.\、\s]\s*/, '');
    if (!cleanText) return;

    const btn = document.createElement('button');
    btn.className = 'action-btn-clean';
    btn.textContent = cleanText;

    btn.addEventListener('click', function() {
      // 视觉反馈
      this.classList.toggle('active');
      this.style.transform = 'scale(0.95)';
      setTimeout(() => {
        this.style.transform = '';
      }, 100);

      // 执行追加
      appendToInput(cleanText);
    });

    buttonGroup.appendChild(btn);
  });
})();
</script>
</body>
</html>
