function appendToInput(text) {
  try {
    // 优先尝试特定的 API 触发
    if (window.parent && window.parent.triggerSlash) {
      window.parent.triggerSlash(`/appendinput ${text}`);
      return;
    }
    // 通用的输入框定位逻辑
    const doc = window.parent ? window.parent.document : document;
    const input = doc.querySelector('#send_textarea') || 
                 doc.querySelector('textarea[placeholder*="发送"]') ||
                 doc.querySelector('textarea') ||
                 doc.querySelector('input[type="text"]');

    if (input) {
      const currentValue = input.value.trim();
      input.value = currentValue ? `${currentValue} ${text}` : text;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.focus();
    }
  } catch (error) {
    console.error('追加内容失败:', error);
  }
}

